import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { SessionRecord } from '../types'
import { buildGraph, renderSvg, textTree } from './sankey'
import {
  READ_SESSIONS,
  familyGraphInput,
  orchestrators,
  outcomeOf,
  ownRoot,
  rootOf,
  sessionLink,
  sessionsFolder,
} from './sessions'

// The desktop measures the row in character cells; these turn cells into the
// CSS pixels an Svg is sized in, so the diagram fills the row's width and most
// of the visible height instead of a small default frame.
const CELL_PX = { width: 8.4, height: 18 }
const MIN_SIZE = { width: 640, height: 420 }
const PICKER_SIZE = 8

// Each state a session can end up in has a colour of its own.
const OUTCOME_COLORS: Record<string, string> = {
  Coordinating: '#6C8CFF',
  Active: '#3DA5FF',
  'PR open': '#A98BFA',
  'PR merged': '#34C38F',
  'PR closed': '#FF7A8A',
  Idle: '#F7C548',
  Archived: '#B9BEC9',
}

const sessions = atom({ plugin: 'agent-sankey', key: 'sessions' } as const, [])
const root = atom({ plugin: 'agent-sankey', key: 'root' } as const, null)
const note = atom({ plugin: 'agent-sankey', key: 'note' } as const, null)

// Reads the desktop app's session records: titles, who started whom, turns
// and state, never what was said.
const load = async ($: EngineInterface): Promise<SessionRecord[]> => {
  await update($, note, () => 'Reading sessions…')
  try {
    const home = (await $.env.get('HOME')) ?? ''
    const { exitCode, stdout, stderr } = await $.process.run(
      ['python3', '-c', READ_SESSIONS, sessionsFolder(home)],
      { timeoutMs: 60_000 },
    )
    if (exitCode !== 0) throw new Error(stderr.trim() || `exit ${exitCode}`)
    const records = JSON.parse(stdout) as SessionRecord[]
    await update($, sessions, () => records)
    await update($, note, () => null)
    return records
  } catch (error) {
    await update($, note, () => `Could not read the sessions: ${String(error)}`)
    return []
  }
}

// The orchestrator to draw: one the command named, else this session's own
// family, else the most recently active one.
const pickRoot = (records: readonly SessionRecord[], args: string, ownCliId: string): string | null => {
  const wanted = args.trim().toLowerCase()
  const all = orchestrators(records)
  if (wanted !== '') {
    const named = all.find(r => r.title.toLowerCase().includes(wanted))
    if (named) return named.id
  }
  return ownRoot(records, ownCliId) ?? all[0]?.id ?? null
}

const openSession = async ($: EngineInterface, id: string): Promise<void> => {
  const { exitCode } = await $.process.run(['open', sessionLink(id)]).catch(() => ({ exitCode: 1 }))
  if (exitCode !== 0) $.ui.toast('Could not open that session.')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'sankey',
      description: 'Show an orchestrator session and the sessions it started as a Sankey diagram',
      argumentHint: '[orchestrator name]',
    })

    return next(e)
  })

  // The diagram draws inline in the conversation, in the command's own output row.
  on('command.run', { command: 'sankey' }, async ($, e) => {
    const records = await load($)
    const picked = pickRoot(records, e.args, await $.session.id())
    await update($, root, () => picked)
    if (picked === null) return { text: 'No orchestrator sessions found: none of your sessions has started another.' }
    const { agents, tally, rootTitle } = familyGraphInput(records, picked, await $.clock.now())
    const graph = buildGraph(agents, tally, { rootLabel: rootTitle, unit: ['turn', 'turns'] })

    return { text: `Session family of ${rootTitle}:\n${textTree(graph, 80).join('\n')}` }
  })

  on('ui.render', { component: 'CommandOutput', props: { command: 'sankey' } }, async ($, e) => {
    const records = await read($, sessions)
    const picked = await read($, root)
    const message = await read($, note)
    const now = await $.clock.now()
    const { Box, Text, Button } = $.ui.resolve(e)
    const columns = e.viewport?.columns ?? 100

    if (picked === null || !records.some(r => r.id === picked)) {
      return <Text dimColor>{message ?? 'No orchestrator sessions found.'}</Text>
    }

    const { agents, tally, rootTitle } = familyGraphInput(records, picked, now)
    const graph = buildGraph(agents, tally, {
      rootLabel: rootTitle,
      unit: ['turn', 'turns'],
      outcomeColors: OUTCOME_COLORS,
    })
    const family = records
      .filter(r => rootOf(records, r.id) === picked)
      .sort((a, b) => (a.id === picked ? -1 : b.id === picked ? 1 : b.lastActivityAt - a.lastActivityAt))
    const others = orchestrators(records).slice(0, PICKER_SIZE)

    const picker = (
      <Box gap={1} flexWrap="wrap">
        <Text dimColor>Orchestrator:</Text>
        {others.map(one => (
          <Button
            key={`root-${one.id}`}
            label={one.title}
            variant={one.id === picked ? 'primary' : 'secondary'}
            onPress={() => update($, root, () => one.id)}
          />
        ))}
        <Button key="refresh" label="Refresh" onPress={() => load($)} />
      </Box>
    )
    const opener = (
      <Box flexDirection="column">
        <Text dimColor>Click a session to open it:</Text>
        <Box gap={1} flexWrap="wrap">
          {family.map(one => (
            <Button
              key={`open-${one.id}`}
              label={`${one.id === picked ? '★ ' : '↗ '}${one.title} · ${outcomeOf(one, now)}`}
              onPress={() => openSession($, one.id)}
            />
          ))}
        </Box>
      </Box>
    )

    // The terminal draws no pictures: it gets the flow as text.
    if (e.surface === 'terminal') {
      return (
        <Box flexDirection="column" gap={1}>
          {picker}
          {message !== null && <Text dimColor>{message}</Text>}
          <Box flexDirection="column">
            {textTree(graph, columns).map(line => (
              <Text wrap="truncate-end">{line}</Text>
            ))}
          </Box>
          {opener}
        </Box>
      )
    }

    // The Sankey as a picture, sized to the row: wide as the transcript and
    // most of the visible height. Hover traces a lane; the buttons open sessions.
    const { Svg } = $.ui.resolve(e)
    const width = Math.max(MIN_SIZE.width, Math.round(columns * CELL_PX.width))
    const rows = e.viewport?.rows ?? 40
    const height = Math.max(MIN_SIZE.height, Math.round((rows - 10) * CELL_PX.height))
    return (
      <Box flexDirection="column" gap={1}>
        {picker}
        {message !== null && <Text dimColor>{message}</Text>}
        <Svg
          source={renderSvg(graph, width, null, height)}
          alt={textTree(graph, 80).join('\n')}
          width={width}
          height={height}
          isInteractive
        />
        {opener}
      </Box>
    )
  })
}

