import type { AgentNode, Tally } from '../types'

export const MAIN = 'main'
export const SELF = 'main:self'
const MAX_TOOLS = 12

export type Node = {
  id: string
  label: string
  column: number
  value: number
  color: string
  status?: string
}

export type Link = { source: string; target: string; value: number }

export type Graph = {
  nodes: Node[]
  links: Link[]
  columns: number
  total: number
  agentCount: number
  // What a flow counts, singular and plural ("tool call", "turn").
  unit: [string, string]
  rootLabel: string
}

export type GraphOptions = {
  rootLabel?: string
  unit?: [string, string]
  // Fixed colours for nodes in the last column, by label (a session's outcome).
  outcomeColors?: Record<string, string>
}

export const count = (graph: Graph, n: number): string => `${n} ${n === 1 ? graph.unit[0] : graph.unit[1]}`

// Light but saturated enough to tell apart on the white card.
const PALETTE = ['#FF9F6B', '#5CCB8A', '#FF7A8A', '#A98BFA', '#3CC7C0', '#F7C548', '#F78FC4', '#6FB2FF', '#B5D86A', '#FFB86B']
const ORCHESTRATOR = '#6C8CFF'

// The label a call is counted under, or null for a call drawn as a spawn link.
export const toolLabel = (tool: string, input: Record<string, unknown> = {}): string | null => {
  if (tool === 'Agent' || tool === 'Task') return null
  if (tool === 'SendMessage') {
    const to = input.to ?? input.recipient
    return typeof to === 'string' && to !== '' ? `Message → ${to}` : 'Message'
  }
  const mcp = /^mcp__([^_]+(?:_[^_]+)*)__(.+)$/.exec(tool)
  if (mcp) return `MCP ${mcp[1]}`
  return tool
}

const sum = (counts: Record<string, number> | undefined): number =>
  Object.values(counts ?? {}).reduce((a, b) => a + b, 0)

// Columns: the orchestrator, its children by depth, then the tools they called.
// A link's width is tool calls: parent to child carries the child's whole subtree,
// agent to tool what that agent called itself.
export const buildGraph = (agents: readonly AgentNode[], given: Tally, options: GraphOptions = {}): Graph => {
  const rootLabel = options.rootLabel ?? 'Orchestrator'
  // The orchestrator's own calls flow through a node of their own beside its
  // children, so every flow into the tools comes from the middle columns.
  const { [MAIN]: ownCalls, ...rest } = given
  const tally: Tally = sum(ownCalls) > 0 ? { ...rest, [SELF]: ownCalls ?? {} } : rest
  const known = new Map<string, AgentNode>()
  if (sum(ownCalls) > 0) known.set(SELF, { id: SELF, label: `${rootLabel} itself`, parentId: MAIN, status: 'running' })
  known.set(MAIN, { id: MAIN, label: rootLabel, parentId: null, status: 'running' })
  for (const agent of agents) if (agent.id !== MAIN) known.set(agent.id, agent)
  for (const id of Object.keys(tally)) {
    if (!known.has(id)) known.set(id, { id, label: `Agent ${id.slice(0, 8)}`, parentId: MAIN, status: 'completed' })
  }

  const parentOf = (id: string): string | null => {
    if (id === MAIN) return null
    const parent = known.get(id)?.parentId ?? MAIN
    return known.has(parent) && parent !== id ? parent : MAIN
  }
  const children = new Map<string, string[]>()
  for (const id of known.keys()) {
    const parent = parentOf(id)
    if (parent !== null) children.set(parent, [...(children.get(parent) ?? []), id])
  }

  const depth = new Map<string, number>([[MAIN, 0]])
  const subtree = new Map<string, number>()
  const walk = (id: string, d: number, seen: Set<string>): number => {
    depth.set(id, d)
    seen.add(id)
    let total = sum(tally[id])
    for (const child of children.get(id) ?? []) if (!seen.has(child)) total += walk(child, d + 1, seen)
    subtree.set(id, total)
    return total
  }
  const total = walk(MAIN, 0, new Set())
  const agentDepth = Math.max(...depth.values())
  const toolColumn = agentDepth + 1

  const colorOf = new Map<string, string>([[MAIN, ORCHESTRATOR]])
  const nodes: Node[] = []
  const links: Link[] = []
  const ordered = [...depth.keys()].sort((a, b) => (subtree.get(b) ?? 0) - (subtree.get(a) ?? 0))
  let paint = 0
  for (const id of ordered) {
    if (id === SELF) colorOf.set(id, ORCHESTRATOR)
    else if (id !== MAIN) colorOf.set(id, PALETTE[paint++ % PALETTE.length] ?? ORCHESTRATOR)
    const agent = known.get(id)
    nodes.push({
      id,
      label: agent?.label ?? id,
      column: depth.get(id) ?? 0,
      value: subtree.get(id) ?? 0,
      color: colorOf.get(id) ?? ORCHESTRATOR,
      status: agent?.status,
    })
    const parent = parentOf(id)
    if (parent !== null) links.push({ source: parent, target: id, value: subtree.get(id) ?? 0 })
  }

  // The busiest tools by name; the rest fold into Other.
  const toolTotals = new Map<string, number>()
  for (const counts of Object.values(tally)) {
    for (const [tool, n] of Object.entries(counts)) toolTotals.set(tool, (toolTotals.get(tool) ?? 0) + n)
  }
  const top = new Set([...toolTotals.entries()].sort((a, b) => b[1] - a[1]).slice(0, MAX_TOOLS).map(([t]) => t))
  const toolOf = (tool: string): string => (top.has(tool) ? tool : 'Other')
  const toolLinks = new Map<string, number>()
  const biggest = new Map<string, { agent: string; n: number }>()
  for (const [agent, counts] of Object.entries(tally)) {
    if (!depth.has(agent)) continue
    for (const [tool, n] of Object.entries(counts)) {
      const key = `${agent}\u0000tool:${toolOf(tool)}`
      toolLinks.set(key, (toolLinks.get(key) ?? 0) + n)
    }
  }
  const toolNodes = new Map<string, number>()
  for (const [key, n] of toolLinks) {
    const [agent = MAIN, target = ''] = key.split('\u0000')
    links.push({ source: agent, target, value: n })
    toolNodes.set(target, (toolNodes.get(target) ?? 0) + n)
    if ((biggest.get(target)?.n ?? -1) < n) biggest.set(target, { agent, n })
  }
  for (const [id, value] of [...toolNodes.entries()].sort((a, b) => b[1] - a[1])) {
    nodes.push({
      id,
      label: id.slice('tool:'.length),
      column: toolColumn,
      value,
      color: options.outcomeColors?.[id.slice('tool:'.length)] ?? colorOf.get(biggest.get(id)?.agent ?? MAIN) ?? ORCHESTRATOR,
    })
  }

  return {
    nodes,
    links,
    columns: toolColumn + 1,
    total,
    agentCount: [...depth.keys()].filter(id => id !== MAIN && id !== SELF).length,
    unit: options.unit ?? ['tool call', 'tool calls'],
    rootLabel,
  }
}

const escape = (text: string): string =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

const short = (text: string, max: number): string => (text.length > max ? `${text.slice(0, max - 1)}…` : text)

type Box = { x: number; y: number; h: number }

// The agents and tools a focused agent touches: its line up to the
// orchestrator, everything beneath it, and the tools those agents called.
export const relatedTo = (graph: Graph, focus: string | null): Set<string> | null => {
  if (focus === null || !graph.nodes.some(n => n.id === focus)) return null
  const related = new Set<string>([focus])
  const parentOf = new Map(graph.links.filter(l => !l.target.startsWith('tool:')).map(l => [l.target, l.source]))
  for (let up = parentOf.get(focus); up !== undefined; up = parentOf.get(up)) related.add(up)
  const below = [focus]
  while (below.length > 0) {
    const id = below.pop() ?? ''
    for (const link of graph.links) {
      if (link.source !== id || related.has(link.target)) continue
      related.add(link.target)
      if (!link.target.startsWith('tool:')) below.push(link.target)
    }
  }
  return related
}

export const renderSvg = (
  graph: Graph,
  width: number,
  focus: string | null = null,
  height?: number,
): string => {
  const W = Math.max(480, Math.round(width))
  const perColumn = new Map<number, Node[]>()
  for (const node of graph.nodes) perColumn.set(node.column, [...(perColumn.get(node.column) ?? []), node])
  const busiest = Math.max(1, ...[...perColumn.values()].map(list => list.length))
  const H = Math.max(340, Math.round(height ?? Math.min(900, busiest * 40 + 110)), busiest * 30 + 110)
  const top = 54
  const bottom = 34
  const gap = 12
  const nodeW = 16
  const side = 28
  const usable = H - top - bottom
  const scale = Math.min(
    ...[...perColumn.values()].map(list => {
      const values = list.reduce((a, n) => a + Math.max(n.value, 0), 0)
      return values === 0 ? Infinity : (usable - gap * (list.length - 1)) / values
    }),
  )
  const k = Number.isFinite(scale) ? scale : 1
  const heightOf = (value: number): number => Math.max(3, value * k)

  const boxes = new Map<string, Box>()
  const columnX = (column: number): number =>
    graph.columns <= 1 ? side : side + (column * (W - 2 * side - nodeW)) / (graph.columns - 1)
  // Columns left to right; the last column is ordered by where its flows come
  // from, so bands cross as little as they can.
  const middleOf = (id: string): number => {
    const box = boxes.get(id)
    return box === undefined ? 0 : box.y + box.h / 2
  }
  const lastColumn = graph.columns - 1
  for (const [column, unordered] of [...perColumn.entries()].sort((a, b) => a[0] - b[0])) {
    const list =
      column !== lastColumn
        ? unordered
        : [...unordered].sort((a, b) => {
            const at = (id: string): number => {
              const into = graph.links.filter(l => l.target === id)
              const weight = into.reduce((sum, l) => sum + l.value, 0) || 1
              return into.reduce((sum, l) => sum + middleOf(l.source) * l.value, 0) / weight
            }
            return at(a.id) - at(b.id)
          })
    const span = list.reduce((a, n) => a + heightOf(n.value), 0) + gap * (list.length - 1)
    let y = top + (usable - span) / 2
    for (const node of list) {
      boxes.set(node.id, { x: columnX(column), y, h: heightOf(node.value) })
      y += heightOf(node.value) + gap
    }
  }

  const related = relatedTo(graph, focus)
  const ancestors = new Set<string>()
  if (focus !== null) {
    const parentOf = new Map(graph.links.filter(l => !l.target.startsWith('tool:')).map(l => [l.target, l.source]))
    for (let up = parentOf.get(focus); up !== undefined; up = parentOf.get(up)) ancestors.add(up)
  }
  // Above the focus only the path down to it lights, not the ancestors' own tools.
  const isLit = (link: Link): boolean =>
    related !== null &&
    related.has(link.source) &&
    related.has(link.target) &&
    !(ancestors.has(link.source) && link.target.startsWith('tool:'))
  const index = new Map(graph.nodes.map((n, i) => [n.id, i]))
  const colorOf = new Map(graph.nodes.map(n => [n.id, n.color]))
  const outAt = new Map<string, number>()
  const inAt = new Map<string, number>()
  const sorted = [...graph.links].sort(
    (a, b) => (boxes.get(a.target)?.y ?? 0) - (boxes.get(b.target)?.y ?? 0),
  )
  const name = (id: string) => graph.nodes.find(n => n.id === id)?.label ?? id
  const ribbons: string[] = []
  const gradients: string[] = []
  // Bands leave a bar in the order of where they go, and arrive in the order of
  // where they came from, so they do not cross at either end.
  const arrival = new Map<Link, number>()
  for (const link of [...graph.links].sort((a, b) => middleOf(a.source) - middleOf(b.source))) {
    if (link.value <= 0 || !boxes.has(link.source)) continue
    arrival.set(link, inAt.get(link.target) ?? 0)
    inAt.set(link.target, (inAt.get(link.target) ?? 0) + link.value * k)
  }
  for (const link of sorted) {
    const from = boxes.get(link.source)
    const to = boxes.get(link.target)
    if (!from || !to || link.value <= 0) continue
    const h = link.value * k
    const y0 = from.y + (outAt.get(link.source) ?? 0)
    const y1 = to.y + (arrival.get(link) ?? 0)
    outAt.set(link.source, (outAt.get(link.source) ?? 0) + h)
    const x0 = from.x + nodeW
    const x1 = to.x
    const mid = (x0 + x1) / 2
    const d = `M${x0},${y0} C${mid},${y0} ${mid},${y1} ${x1},${y1} L${x1},${y1 + h} C${mid},${y1 + h} ${mid},${y0 + h} ${x0},${y0 + h} Z`
    const lit = related === null ? 'flow' : isLit(link) ? 'flow lit' : 'flow dim'
    const gradient = `g${ribbons.length}`
    gradients.push(
      `<linearGradient id="${gradient}" gradientUnits="userSpaceOnUse" x1="${x0}" y1="0" x2="${x1}" y2="0"><stop offset="0" stop-color="${colorOf.get(link.source)}"/><stop offset="1" stop-color="${colorOf.get(link.target)}"/></linearGradient>`,
    )
    ribbons.push(
      `<path class="${lit} s${index.get(link.source)} t${index.get(link.target)}" d="${d}" fill="url(#${gradient})"><title>${escape(
        `${name(link.source)} → ${name(link.target)}: ${count(graph, link.value)}`,
      )}</title></path>`,
    )
  }

  // Labels may run over the bands to their right, up to most of the gap to the next column.
  const labelRoom = Math.max(14, Math.floor((W / Math.max(2, graph.columns - 1)) * 0.85 / 7.6))
  const rects: string[] = []
  const labels: string[] = []
  const hoverRules: string[] = []
  for (const node of graph.nodes) {
    const box = boxes.get(node.id)
    if (!box) continue
    const i = index.get(node.id)
    hoverRules.push(`.chart:has(.n${i}:hover) .s${i},.chart:has(.n${i}:hover) .t${i}{fill-opacity:.8}`)
    const isRunning = ['running', 'pending', 'waiting', 'Active'].includes(node.status ?? '')
    const isFocus = node.id === focus
    const isDim = related !== null && !related.has(node.id)
    const tip = `${node.label}: ${count(graph, node.value)}${node.status && node.id.startsWith('tool:') === false ? ` · ${node.status}` : ''}`
    const outline = isFocus
      ? ' stroke="#2B2D33" stroke-width="2"'
      : isRunning && node.id !== MAIN && node.id !== SELF
        ? ' stroke="#2B2D33" stroke-width="1.2" stroke-dasharray="3 2"'
        : ''
    rects.push(
      `<rect class="node n${i}${isDim ? ' dim' : ''}" x="${box.x}" y="${box.y}" width="${nodeW}" height="${box.h}" rx="3" fill="${node.color}"${outline}><title>${escape(tip)}</title></rect>`,
    )
    const isTool = node.column === lastColumn && node.id.startsWith('tool:')
    const x = isTool ? box.x - 6 : box.x + nodeW + 6
    const anchor = isTool ? 'end' : 'start'
    const text = `${short(node.label, labelRoom)} ${node.value}`
    labels.push(
      `<text class="${isDim ? 'dim' : ''}" x="${x}" y="${box.y + box.h / 2}" text-anchor="${anchor}" dominant-baseline="middle"${isFocus ? ' font-weight="800"' : ''}>${escape(text)}</text>`,
    )
  }

  const style = [
    '.flow{fill-opacity:.42;transition:fill-opacity .15s}',
    '.flow.lit{fill-opacity:.7}.flow.dim{fill-opacity:.08}',
    '.node{transition:opacity .15s}.node.dim,text.dim{opacity:.35}',
    '.chart:has(.node:hover) .flow,.chart:has(.flow:hover) .flow{fill-opacity:.1}',
    '.chart .flow:hover{fill-opacity:.8}',
    '.node:hover{filter:brightness(.9)}',
    'text{pointer-events:none}',
    ...hoverRules,
  ].join('')
  const heading = `${graph.rootLabel} · ${graph.agentCount} session${graph.agentCount === 1 ? '' : 's'} started · ${count(graph, graph.total)}`
  return [
    `<svg class="chart" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" font-family="system-ui, -apple-system, sans-serif">`,
    `<style>${style}</style>`,
    `<defs>${gradients.join('')}</defs>`,
    `<rect width="${W}" height="${H}" rx="12" fill="#FBFBFD" stroke="#E4E6EB"/>`,
    `<text x="${W / 2}" y="32" text-anchor="middle" fill="#2B2D33" font-size="18" font-weight="700">${escape(heading)}</text>`,
    `<g>${ribbons.join('')}</g>`,
    `<g>${rects.join('')}</g>`,
    `<g fill="#2B2D33" font-size="14" font-weight="600" stroke="#FBFBFD" stroke-width="3" paint-order="stroke">${labels.join('')}</g>`,
    `<text x="${W / 2}" y="${H - 12}" text-anchor="middle" fill="#8A8D96" font-size="12">Width = ${graph.unit[1]} · hover a bar or band to trace it · click a session above to open it</text>`,
    '</svg>',
  ].join('')
}

// The same flow as text, for a surface that cannot draw SVG.
export const textTree = (graph: Graph, columns: number): string[] => {
  const lines: string[] = []
  const barRoom = Math.max(6, Math.min(24, columns - 40))
  const bar = (value: number): string => '█'.repeat(Math.max(value > 0 ? 1 : 0, Math.round((value / Math.max(1, graph.total)) * barRoom)))
  const byId = new Map(graph.nodes.map(n => [n.id, n]))
  const kids = (id: string) =>
    graph.links.filter(l => l.source === id && !l.target.startsWith('tool:')).map(l => l.target)
  const tools = (id: string) =>
    graph.links
      .filter(l => l.source === id && l.target.startsWith('tool:'))
      .sort((a, b) => b.value - a.value)
      .map(l => `${l.target.slice(5)} ${l.value}`)
  const walk = (id: string, indent: string): void => {
    const node = byId.get(id)
    if (!node) return
    lines.push(`${indent}${node.label} ${bar(node.value)} ${node.value}${node.status && id !== MAIN && id !== SELF ? ` (${node.status})` : ''}`)
    const own = tools(id)
    if (own.length > 0) lines.push(`${indent}  ${graph.unit[0] === 'turn' ? 'state' : 'tools'}: ${own.join(', ')}`)
    for (const child of kids(id)) walk(child, `${indent}  `)
  }
  walk(MAIN, '')
  return lines
}

// What the details line under the diagram says of one agent.
export const detailsOf = (graph: Graph, id: string): string[] => {
  const node = graph.nodes.find(n => n.id === id)
  if (node === undefined) return []
  const parent = graph.links.find(l => l.target === id && !l.source.startsWith('tool:'))?.source
  const parentName = graph.nodes.find(n => n.id === parent)?.label
  const children = graph.links.filter(l => l.source === id && !l.target.startsWith('tool:'))
  const tools = graph.links
    .filter(l => l.source === id && l.target.startsWith('tool:'))
    .sort((a, b) => b.value - a.value)
    .map(l => `${l.target.slice(5)} ${l.value}`)
  const head = [node.label, node.status && node.id !== SELF ? node.status : undefined, count(graph, node.value)]
  return [
    head.filter(Boolean).join(' · '),
    ...(parentName !== undefined && parent !== MAIN ? [`Spawned by ${parentName}`] : []),
    ...(tools.length > 0 ? [`${graph.unit[0] === 'turn' ? 'State' : 'Called'}: ${tools.join(', ')}`] : []),
    ...(children.length > 0
      ? [`${graph.unit[0] === 'turn' ? 'Started' : 'Subagents'}: ${children.map(l => `${graph.nodes.find(n => n.id === l.target)?.label ?? l.target} ${l.value}`).join(', ')}`]
      : []),
  ]
}

