import type { AgentNode, SessionRecord, Tally } from '../types'

// Reads the desktop app's session records and prints only the fields the
// diagram needs: titles, who started whom, turns and outcome. Nothing of what
// was said in a session is read out.
export const READ_SESSIONS = `
import json, glob, os, sys
out = []
for path in glob.glob(os.path.join(sys.argv[1], '*', '*', 'local_*.json')):
    try:
        with open(path) as f:
            d = json.load(f)
    except Exception:
        continue
    spawned = d.get('spawnedFrom') or {}
    prs = [p for p in (d.get('prs') or []) if isinstance(p, dict)]
    pr_state = d.get('prState') or (prs[-1].get('state') if prs else None)
    out.append({
        'id': d.get('sessionId'),
        'title': d.get('title') or 'Untitled session',
        'parentId': spawned.get('sessionId'),
        'turns': d.get('completedTurns') or 0,
        'isArchived': bool(d.get('isArchived')),
        'prState': pr_state,
        'lastActivityAt': d.get('lastActivityAt') or 0,
        'cliSessionIds': [i for i in [d.get('cliSessionId')] + list(d.get('priorCliSessionIds') or []) if i],
    })
print(json.dumps(out))
`

export const sessionsFolder = (home: string): string =>
  `${home}/Library/Application Support/Claude/claude-code-sessions`

// A link that opens a session in the desktop app.
export const sessionLink = (id: string): string => `claude://claude.ai/epitaxy/${id}`

const ACTIVE_MS = 10 * 60 * 1000

export const outcomeOf = (session: SessionRecord, now: number): string => {
  if (session.prState === 'MERGED') return 'PR merged'
  if (session.prState === 'OPEN') return 'PR open'
  if (session.prState === 'CLOSED') return 'PR closed'
  if (session.isArchived) return 'Archived'
  if (now - session.lastActivityAt < ACTIVE_MS) return 'Active'
  return 'Idle'
}

const byId = (records: readonly SessionRecord[]) => new Map(records.map(r => [r.id, r]))

export const rootOf = (records: readonly SessionRecord[], id: string): string => {
  const all = byId(records)
  let at = id
  for (let hops = 0; hops < 50; hops++) {
    const parent = all.get(at)?.parentId
    if (parent === null || parent === undefined || !all.has(parent)) return at
    at = parent
  }
  return at
}

// Sessions that started others, the most recently active family first.
export const orchestrators = (records: readonly SessionRecord[]): SessionRecord[] => {
  const all = byId(records)
  const latest = new Map<string, number>()
  for (const r of records) {
    if (!r.parentId || !all.has(r.parentId)) continue
    const root = rootOf(records, r.id)
    latest.set(root, Math.max(latest.get(root) ?? 0, r.lastActivityAt, all.get(root)?.lastActivityAt ?? 0))
  }
  return [...latest.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([id]) => all.get(id))
    .filter((r): r is SessionRecord => r !== undefined)
}

// The family the session running this mod belongs to, by its transcript id.
export const ownRoot = (records: readonly SessionRecord[], cliSessionId: string): string | null => {
  const own = records.find(r => r.cliSessionIds.includes(cliSessionId))
  if (own === undefined) return null
  const root = rootOf(records, own.id)
  return records.some(r => r.parentId !== null && rootOf(records, r.id) === root && r.id !== root) ? root : null
}

// The family as the diagram's input: the root stands as the orchestrator
// (`main`), each session's turns flow on to the column of outcomes.
export const familyGraphInput = (
  records: readonly SessionRecord[],
  root: string,
  now: number,
): { agents: AgentNode[]; tally: Tally; rootTitle: string } => {
  const family = records.filter(r => rootOf(records, r.id) === root)
  const key = (id: string): string => (id === root ? 'main' : id)
  const agents: AgentNode[] = family
    .filter(r => r.id !== root)
    .map(r => ({
      id: r.id,
      label: r.title,
      parentId: r.parentId ? key(r.parentId) : 'main',
      status: outcomeOf(r, now),
    }))
  const tally: Tally = {}
  for (const r of family) {
    const outcome = r.id === root ? 'Coordinating' : outcomeOf(r, now)
    tally[key(r.id)] = { [outcome]: Math.max(1, r.turns) }
  }
  return { agents, tally, rootTitle: byId(records).get(root)?.title ?? 'Orchestrator' }
}

