// One agent of the diagram; the orchestrator is `main`.
export type AgentNode = { id: string; label: string; parentId: string | null; status: string }

// Flow by agent id, then by what it flows into (a tool, or a session's state).
export type Tally = Record<string, Record<string, number>>

// One desktop session as the diagram reads it: no conversation content.
export type SessionRecord = {
  id: string
  title: string
  parentId: string | null
  turns: number
  isArchived: boolean
  prState: string | null
  lastActivityAt: number
  cliSessionIds: string[]
}

declare module 'claude-code' {
  interface PluginState {
    'agent-sankey': {
      sessions: SessionRecord[]
      // The orchestrator session whose family is drawn.
      root: string | null
      note: string | null
    }
  }
}
